export const meta = {
  "slug": "dropdown-menu",
  "name": "Dropdown Menu",
  "family": "Overlays",
  "collection": "Surfaces",
  "component": "createLinearDropdownMenu"
};

export function createLinearDropdownMenu(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderLinearScene(svg, current);
  };
  render();
  const controller = bindLinearScene(root, current);
  return {
    replay: controller.replay,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
  };
}
